import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { deleteSpaceFile } from "../handlers/deleteSpaceFile";
import type { ApiError } from "../runtime/client";
import type { DeleteSpaceFileRequest } from "../types/DeleteSpaceFileRequest";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof deleteSpaceFile>>;
type Vars = { spacePk: SpacePartition; req: DeleteSpaceFileRequest };

export function useDeleteSpaceFile(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => deleteSpaceFile(vars.spacePk, vars.req),
    ...options,
  });
}
